import http from "k6/http";

import { BASE_URL } from "./config.js";

// Coffee ids are generated by the database, so a scenario that needs one reads the catalog first.
// Module variables are per virtual user in k6, so each user makes this request once.
let idsBySlug;

export function coffeeId(slug) {
  if (!idsBySlug) {
    const coffees = http
      .get(`${BASE_URL}/api/v1/coffees`, { tags: { name: "setup coffees" } })
      .json().coffees;
    idsBySlug = Object.fromEntries(coffees.map((coffee) => [coffee.slug, coffee.id]));
  }
  return idsBySlug[slug];
}
